function setupCityInput(selector) {
        let firstFilteredOption;

        $(selector).autocomplete({
            source: function (request, response) {
                const matcher = new RegExp("^" + $.ui.autocomplete.escapeRegex(request.term), "i");

                const filtered = $.map(locations, function (loc) {
                    if (matcher.test(loc.labelUa) || matcher.test(loc.labelRu)) {
                        return {
                            label: loc.labelUa,
                            value: loc.value
                        };
                    }
                });

                firstFilteredOption = filtered.length ? filtered[0] : null;
                response(filtered);
            },
            select: function (event, ui) {
                $(selector).val(ui.item.label);
                $(selector + "-id").val(ui.item.value);
                return false;
            }
        }).autocomplete("instance")._renderItem = function (ul, item) {
            const [city, country] = item.label.split(", ");
            return $("<li>")
                .append("<div><b>" + city + "</b>, " + country + "</div>")
                .appendTo(ul);
        };

        $(selector).on("input", function () {
            $(selector + "-id").val("");
        });

        $(selector).blur(function () {
            if (!$(selector + "-id").val() && $(selector).val() && firstFilteredOption) {
                $(selector).val(firstFilteredOption.label);
                $(selector + "-id").val(firstFilteredOption.value);
            }
        });
    }

    document.addEventListener("DOMContentLoaded", function () {
        setupCityInput("#search-city-input-from");
        setupCityInput("#search-city-input-to");

        const from = document.getElementById("search-city-input-from");
        const fromId = document.getElementById("search-city-input-from-id");
        const to = document.getElementById("search-city-input-to");
        const toId = document.getElementById("search-city-input-to-id");

        const submitBtn = document.querySelector(".search-find");

        submitBtn.addEventListener("click", function (event) {
            if (!fromId.value) {
                from.setCustomValidity("Виберіть місто");
                from.reportValidity();
                event.preventDefault();
                return;
            }
            if (!toId.value) {
                to.setCustomValidity("Виберіть місто");
                to.reportValidity();
                event.preventDefault();
                return;
            }
        });

        from.addEventListener("input", () => from.setCustomValidity(""));
        to.addEventListener("input", () => to.setCustomValidity(""));

        // Swap logic (desktop + mobile)
        function swapInputs() {
            const tmp = from.value;
            const tmpId = fromId.value;

            from.value = to.value;
            fromId.value = toId.value;

            to.value = tmp;
            toId.value = tmpId;
        }

        document.getElementById("swap-cities").onclick = swapInputs;
        document.getElementById("swap-cities-mobile").onclick = swapInputs;



    });

    function setupAutocomplete(input, list) {
        input.addEventListener("input", () => {
            const q = input.value.toLowerCase();
            list.innerHTML = "";
            if (!q) return;

            const suggestions = cities.filter(c => c.toLowerCase().includes(q));

            suggestions.forEach(s => {
                const item = document.createElement("div");
                item.className = "autocomplete-item";
                item.textContent = s;
                item.onclick = () => { input.value = s; list.innerHTML = ""; };
                list.appendChild(item);
            });
        });
    }


    const calendar = document.getElementById("calendar");
    const dateVisible = document.getElementById("date-visible");
    const dateHidden = document.getElementById("date");

    let curr = new Date();

    function renderCalendar() {
        calendar.innerHTML = "";

        // HEADER
        const header = document.createElement("div");
        header.className = "calendar-header";
        header.innerHTML = `
        <button class="button-next-prev" id="prev-month"><img src="/images/mybus/calendar_arrow.svg" style="height: 16px; width: 16px; transform: rotate(180deg)" ></button>
        <span>${curr.toLocaleString("uk-UA", { month: "long" })} ${curr.getFullYear()}</span>
        <button class="button-next-prev" id="next-month"><img src="/images/mybus/calendar_arrow.svg" style="height: 16px; width: 16px"></button>
    `;
        calendar.appendChild(header);

        // GRID
        const grid = document.createElement("div");
        grid.className = "calendar-grid";

        // WEEKDAY ROW
        const weekdays = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Нд"];
        weekdays.forEach(w => {
            const wd = document.createElement("div");
            wd.className = "calendar-weekday";
            wd.textContent = w;
            grid.appendChild(wd);
        });

        // FIRST DAY OF MONTH
        let firstDay = new Date(curr.getFullYear(), curr.getMonth(), 1).getDay();
        firstDay = firstDay === 0 ? 7 : firstDay; // Sunday -> 7

        // EMPTY CELLS
        for (let i = 1; i < firstDay; i++) {
            grid.appendChild(document.createElement("div"));
        }

        // TODAY (reference for disabling past dates)
        const today = new Date();
        today.setHours(0,0,0,0);

        const daysInMonth = new Date(curr.getFullYear(), curr.getMonth()+1, 0).getDate();

        for (let d = 1; d <= daysInMonth; d++) {
            const day = document.createElement("div");
            day.className = "calendar-day";
            day.textContent = d;

            const dayDate = new Date(curr.getFullYear(), curr.getMonth(), d);

            // DISABLE PAST DATES
            if (dayDate < today) {
                day.classList.add("disabled-day");
            } else {
                // ACTIVE DAYS
                day.onclick = () => {
                    const year = curr.getFullYear();
                    const month = curr.getMonth() + 1;

                    const formattedBackend =
                        `${year}-${String(month).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
                    dateHidden.value = formattedBackend;

                    const formattedVisible = new Date(year, curr.getMonth(), d)
                        .toLocaleDateString("uk-UA", {
                            day: "numeric",
                            month: "long"
                        });
                    dateVisible.value = formattedVisible;
                    calendar.classList.add("hidden");
                };
            }

            grid.appendChild(day);
        }

        calendar.appendChild(grid);

        document.getElementById("prev-month").onclick = () => {
            curr.setMonth(curr.getMonth() - 1);
            renderCalendar();
        };
        document.getElementById("next-month").onclick = () => {
            curr.setMonth(curr.getMonth() + 1);
            renderCalendar();
        };
    }

    dateVisible.addEventListener("click", () => {
        const rect = dateVisible.getBoundingClientRect();
        calendar.style.left = rect.left + "px";
        calendar.classList.remove("hidden");
        renderCalendar();
    });


    document.addEventListener("click", (e) => {
        const target = e.target;
        if (
            !calendar.contains(target) &&
            !dateVisible.contains(target) &&
            !target.closest(".button-next-prev")
        ) {
            calendar.classList.add("hidden");
        }
    });




    const passBox = document.getElementById("passenger-box");
    const passVisible = document.getElementById("pass-visible");
    const passHidden = document.getElementById("passengers");
    const passCount = document.getElementById("pass-count");

    let count = 1;

    passVisible.addEventListener("click", () => {
        const rect = passVisible.getBoundingClientRect();
        passBox.style.left = rect.left + "px";
        passBox.classList.remove("hidden");
    });

    document.getElementById("plus-pass").onclick = () => {
        count++;
        passCount.textContent = count;
        passVisible.value = count;
        passHidden.value = count;
    };

    document.getElementById("minus-pass").onclick = () => {
        if (count > 1) count--;
        passCount.textContent = count;
        passVisible.value = count;
        passHidden.value = count;
    };

    document.addEventListener("click", (e) => {
        if (!passBox.contains(e.target) && !passVisible.contains(e.target)) {
            passBox.classList.add("hidden");
        }
    });

