document.addEventListener("DOMContentLoaded", () => {
        const faqItems = document.querySelectorAll(".faq-item");

        faqItems.forEach((item) => {
            const question = item.querySelector(".faq-question");
            const answer = item.querySelector(".faq-answer");
            const icon = item.querySelector(".toggle-icon");

            // initial style
            answer.style.maxHeight = "0";
            answer.style.opacity = "0";
            answer.style.overflow = "hidden";
            answer.style.transition = "max-height 0.4s ease, opacity 0.4s ease";

            question.addEventListener("click", () => {
                const isOpen = item.classList.contains("open");

                if (!isOpen) {
                    item.classList.add("open");
                    icon.src = "../images/mybus/fag_icon_minus.svg";
                    answer.style.display = "block";

                    // first expand, then fade in
                    const height = Math.ceil(answer.scrollHeight);
                    answer.style.maxHeight = height + "px";
                    setTimeout(() => {
                        answer.style.opacity = "1";
                    }, 150);
                } else {
                    icon.src = "../images/mybus/faq_icon.svg";
                    answer.style.opacity = "0";

                    // force reflow before collapsing
                    const height = answer.scrollHeight;
                    answer.style.maxHeight = 0;
                    void answer.offsetHeight; // forces reflow
                    answer.style.maxHeight = "0";

                    // wait for transition to finish before hiding
                    setTimeout(() => {
                        answer.style.display = "none";
                        item.classList.remove("open");
                    }, 400);
                }
            });
        });
    });

